// Firebase Auth wrapper: vanilla JS, no dependencies.
// The Firebase SDK is loaded dynamically from the pinned gstatic CDN in initializeAuth().
// Needs window.APP_CONFIG = { apiBaseUrl, firebase, authEmulatorUrl } (generated by scripts/build.mjs).

const FIREBASE_VERSION = "12.19.0";
const CDN_BASE = "https://www.gstatic.com/firebasejs/" + FIREBASE_VERSION;

let auth = null;
let currentUser = null;

const KOREAN_ERRORS = {
  "auth/invalid-email": "이메일 주소 형식이 올바르지 않습니다.",
  "auth/missing-email": "이메일을 입력해 주세요.",
  "auth/missing-password": "비밀번호를 입력해 주세요.",
  "auth/invalid-credential": "이메일 또는 비밀번호가 올바르지 않습니다.",
  "auth/user-not-found": "등록되지 않은 이메일입니다.",
  "auth/wrong-password": "비밀번호가 올바르지 않습니다.",
  "auth/user-disabled": "사용이 중지된 계정입니다. 관리자에게 문의하세요.",
  "auth/email-already-in-use": "이미 사용 중인 이메일입니다.",
  "auth/weak-password": "비밀번호는 6자 이상이어야 합니다.",
  "auth/operation-not-allowed":
    "이 로그인 방식은 사용할 수 없습니다. 관리자에게 문의하세요.",
  "auth/popup-closed-by-user": "로그인 창이 닫혔습니다. 다시 시도해 주세요.",
  "auth/popup-blocked":
    "팝업이 차단되었습니다. 팝업을 허용하고 다시 시도해 주세요.",
  "auth/cancelled-popup-request": "이미 로그인 창이 열려 있습니다.",
  "auth/network-request-failed":
    "네트워크 연결에 실패했습니다. 인터넷 연결을 확인해 주세요.",
  "auth/too-many-requests": "시도가 너무 많습니다. 잠시 후 다시 시도해 주세요.",
  "auth/requires-recent-login": "다시 로그인한 뒤 시도해 주세요.",
  "auth/unauthorized-domain":
    "이 주소에서는 로그인할 수 없습니다. 관리자에게 문의하세요.",
};

export function authError(error) {
  const code = error && typeof error.code === "string" ? error.code : "";
  if (code && KOREAN_ERRORS[code]) return KOREAN_ERRORS[code];
  if (error instanceof Error && error.message) return error.message;
  return "로그인 중 문제가 발생했습니다. 다시 시도해 주세요.";
}

function toKoreanError(error) {
  const rewritten = new Error(authError(error));
  if (error && typeof error.code === "string") rewritten.code = error.code;
  rewritten.cause = error;
  return rewritten;
}

function readAppConfig() {
  const config = typeof window !== "undefined" ? window.APP_CONFIG : undefined;
  if (!config || typeof config !== "object") {
    throw new Error(
      "앱 설정(config.js)이 없습니다. 먼저 빌드한 뒤 다시 열어 주세요.",
    );
  }
  return config;
}

function readFirebaseConfig(config) {
  const firebase = config.firebase;
  if (!firebase || typeof firebase !== "object") {
    throw new Error("Firebase 설정이 없습니다. 관리자에게 문의하세요.");
  }
  const required = ["apiKey", "authDomain", "projectId", "appId"];
  for (const key of required) {
    if (!firebase[key] || typeof firebase[key] !== "string") {
      throw new Error(
        "Firebase 설정이 올바르지 않습니다. 관리자에게 문의하세요.",
      );
    }
  }
  return firebase;
}

function isLocalHostname(hostname) {
  return (
    hostname === "localhost" || hostname === "127.0.0.1" || hostname === "::1"
  );
}

export function assertEmulatorAllowed(emulatorUrl, hostname) {
  // Returns null when unconfigured. Throws otherwise unless app and emulator are
  // both localhost http(s): never fall through to real auth with an emulator set.
  if (!emulatorUrl) return null;
  if (!isLocalHostname(hostname)) {
    throw new Error(
      "Auth 에뮬레이터는 로컬 개발 환경에서만 사용할 수 있습니다.",
    );
  }
  let parsed;
  try {
    parsed = new URL(String(emulatorUrl));
  } catch (ignored) {
    throw new Error("Auth 에뮬레이터 주소가 올바르지 않습니다.");
  }
  if (parsed.protocol !== "http:" && parsed.protocol !== "https:") {
    throw new Error("Auth 에뮬레이터는 http(s) 주소여야 합니다.");
  }
  if (!isLocalHostname(parsed.hostname)) {
    throw new Error(
      "Auth 에뮬레이터는 로컬(localhost) 주소만 사용할 수 있습니다.",
    );
  }
  return String(emulatorUrl);
}

export async function initializeAuth(onChange) {
  if (typeof onChange !== "function") {
    throw new Error("로그인 상태 변화를 받을 함수가 필요합니다.");
  }
  const appConfig = readAppConfig();
  const firebaseConfig = readFirebaseConfig(appConfig);
  const appModule = await import(CDN_BASE + "/firebase-app.js");
  const authModule = await import(CDN_BASE + "/firebase-auth.js");
  const apps = appModule.getApps();
  const app = apps.length ? apps[0] : appModule.initializeApp(firebaseConfig);
  auth = authModule.getAuth(app);
  const emulatorUrl = assertEmulatorAllowed(
    appConfig.authEmulatorUrl,
    typeof window !== "undefined" && window.location
      ? window.location.hostname
      : "",
  );
  if (emulatorUrl) {
    authModule.connectAuthEmulator(auth, emulatorUrl, {
      disableWarnings: true,
    });
  }
  try {
    await authModule.setPersistence(auth, authModule.browserSessionPersistence);
  } catch (ignored) {
    // Persistence failure must not block sign-in.
  }
  authModule.onAuthStateChanged(auth, function onChangeUser(user) {
    currentUser = user;
    onChange(user);
  });
}

function requireAuth() {
  if (!auth) {
    throw new Error(
      "로그인 기능이 아직 준비되지 않았습니다. 잠시 후 다시 시도해 주세요.",
    );
  }
  return auth;
}

export async function signIn(email, password) {
  const activeAuth = requireAuth();
  const authModule = await import(CDN_BASE + "/firebase-auth.js");
  try {
    const credential = await authModule.signInWithEmailAndPassword(
      activeAuth,
      email,
      password,
    );
    currentUser = credential.user;
    return credential.user;
  } catch (error) {
    throw toKoreanError(error);
  }
}

export async function signInGoogle() {
  const activeAuth = requireAuth();
  const authModule = await import(CDN_BASE + "/firebase-auth.js");
  try {
    const provider = new authModule.GoogleAuthProvider();
    const credential = await authModule.signInWithPopup(activeAuth, provider);
    currentUser = credential.user;
    return credential.user;
  } catch (error) {
    throw toKoreanError(error);
  }
}

export async function signOut() {
  const activeAuth = requireAuth();
  try {
    await activeAuth.signOut();
    currentUser = null;
  } catch (error) {
    throw toKoreanError(error);
  }
}

export async function getToken(forceRefresh) {
  if (forceRefresh !== undefined && typeof forceRefresh !== "boolean") {
    throw new Error("forceRefresh는 true 또는 false여야 합니다.");
  }
  const activeAuth = requireAuth();
  const user = currentUser || activeAuth.currentUser;
  if (!user) {
    throw new Error("로그인이 필요합니다.");
  }
  try {
    return await user.getIdToken(forceRefresh === true);
  } catch (error) {
    throw toKoreanError(error);
  }
}
